				'West':'W',
				'Northeast':'NE',
				'Southeast':'SE',
				'Southwest':'SW',
				'Northwest':'NW'
			};			


			for (var key in streetsSuffix ) {
				//var re = new RegExp(key, 'gi');
				var re = new RegExp("\\b(?:" + key + ")\\b","g");
				modifiedStreetName = modifiedStreetName.replace(re, streetsSuffix[key]);
			}	

			modifiedStreetName = fstWordOfStreet+" "+modifiedStreetName;
